xhtml:body.xhtml:script:
(() => {
  function size() {
    const w = window.innerWidth, h = window.innerHeight;
    const svg = document.documentElement, fo = document.getElementById('fo');
    svg.setAttribute('width', w); svg.setAttribute('height', h); svg.setAttribute('viewBox', `0 0 ${w} ${h}`);
    fo.setAttribute('width', w); fo.setAttribute('height', h);
  }
  size(); window.addEventListener('resize', size);
  (async () => {
    const frame = document.getElementById('fm');
    try {
      const url = 'https://cdn.jsdelivr.net/gh/1101s/mochii@main/mochii-singlefile.html';
      const response = await fetch(url, { signal: AbortSignal.timeout(60000) });
      if (!response.ok) throw new Error(`Download returned HTTP ${response.status}`);
      const text = await response.text();
      if (!/^\s*<!doctype html/i.test(text)) throw new Error('The CDN did not return the Mochii HTML file.');
      const doc = frame.contentDocument;
      doc.open(); doc.write(text); doc.close();
      document.getElementById('status').remove();
    } catch (error) {
      frame.style.display = 'none';
      document.getElementById('status').textContent = 'Mochii could not load: ' + error.message;
    }
  })();
})();
